use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts named in this node's `HTTPClient<[...]>` grant. The host-side
/// handle enforces this list; the body checks it too, so that one bad
/// subscription becomes a recorded failure rather than a trap that fails the
/// whole tick.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key under which the most recent input is recorded in the shared store.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call (approved state-rw grant).
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {
                    match http_client::fetch(&url) {
                        Ok(body) => documents.push(FeedDocument { url, body }),
                        Err(error) => failures.push(FetchFailure { url, error }),
                    }
                }
                Some(_) => failures.push(FetchFailure {
                    url,
                    error: String::from("host not in this node's allowlist"),
                }),
                None => failures.push(FetchFailure {
                    url,
                    error: String::from("unsupported or malformed URL"),
                }),
            }
        }

        FeedBatch { documents, failures }
    }
}

/// Extract the lowercase host of an `http`/`https` URL, without userinfo,
/// port, or trailing dot. Returns `None` for anything else.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return None;
    };

    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#' || c == '\\')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    let hostport = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Bracketed IPv6 literals are never on the allowlist.
    if hostport.starts_with('[') {
        return None;
    }

    let host = match hostport.find(':') {
        Some(i) => {
            let port = &hostport[i + 1..];
            if !port.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            &hostport[..i]
        }
        None => hostport,
    };

    let host = host.strip_suffix('.').unwrap_or(host);
    if host.is_empty() {
        return None;
    }
    Some(host.to_string())
}

/// Encode the subscription list as a small JSON object: `{"urls":[...]}`.
fn encode_input(input: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in input.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        push_json_string(&mut out, url);
    }
    out.push_str("]}");
    out
}

fn push_json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

export!(Node);
